import{_ as n,a0 as p,w as r,s as d,ao as o,I as l,a1 as i,A as s,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"tmux：適用於重度命令列 Linux 用户的終端複用器 | LCTT x X-CMD","titleTemplate":false,"description":"tmux：適用於重度命令列 Linux 用户的終端複用器 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"tmux：適用於重度命令列 Linux 用户的終端複用器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"tmux：適用於重度命令列 Linux 用户的終端複用器 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180130 tmux - A Powerful Terminal Multiplexer For Heavy Command-Line Linux User","title":"tmux：適用於重度命令列 Linux 用户的終端複用器","tag":"201901","desc":""},"relativePath":"201901/20180130 tmux - A Powerful Terminal Multiplexer For Heavy Command-Line Linux User.md","filePath":"[post].md"}'),u={name:"201901/20180130 tmux - A Powerful Terminal Multiplexer For Heavy Command-Line Linux User.md"};function m(g,e,x,h,c,k){const a=p("Link");return r(),d("div",null,[e[35]||(e[35]=o('<h1 id="tmux-適用於重度命令列-linux-用户的終端複用器" tabindex="-1">tmux：適用於重度命令列 Linux 用户的終端複用器 <a class="header-anchor" href="#tmux-適用於重度命令列-linux-用户的終端複用器" aria-label="Permalink to “tmux：適用於重度命令列 Linux 用户的終端複用器”">​</a></h1><p>tmux 是<ruby>終端複用器<rt>terminal multiplexer</rt></ruby>的縮寫，它允許用户在單個窗口中創建或啓用多個終端（垂直或水平），當你處理不同的問題時，可以在單個窗口中輕鬆訪問和控制它們。</p><p>它使用客户端-服務器模型，允許在用户之間共享會話，也可以將終端連接到 tmux 會話。我們可以根據需要輕鬆移動或重新排列虛擬控制台。終端會話可以從一個虛擬控制台自由切換到另一個。</p><p>tmux 依賴於 <code>libevent</code> 和 <code>ncurses</code> 庫。tmux 在屏幕底部提供了一個狀態行，它顯示當前 tmux 會話的有關信息，例如當前窗口編號、窗口名稱、用户名、主機名、當前時間和日期。</p><p>啓動 tmux 時，它會在一個單獨窗口上創建一個新的會話，並將其顯示在屏幕上。它允許用户在同一個會話中創建任意數量的窗口。</p><p>許多人説它類似於 <code>screen</code>，但我不這麼認為，因為它提供了許多配置選項。</p><p><strong>注意：</strong> <code>Ctrl+b</code> 是 tmux 中的默認命令前綴，因此，要在 tmux 中執行任何操作，你必須先輸入該前綴然後輸入所需的選項。</p><h3 id="tmux-特性" tabindex="-1">tmux 特性 <a class="header-anchor" href="#tmux-特性" aria-label="Permalink to “tmux 特性”">​</a></h3><ul><li>創建任意數量的窗口</li><li>在一個窗口中創建任意數量的窗格</li><li>它允許垂直和水平分割</li><li>分離並重新連接窗口</li><li>客户端-服務器架構，這允許用户之間共享會話</li><li>tmux 提供許多配置技巧</li></ul><p><strong>建議閲讀：</strong></p>',10)),l("ul",null,[l("li",null,[i(a,{href:"https://www.2daygeek.com/tmate-instantly-share-your-terminal-session-to-anyone-in-seconds/"},{default:s(()=>[...e[0]||(e[0]=[t("tmate - 馬上與其他人分享你的終端會話",-1)])]),_:1})]),l("li",null,[i(a,{href:"https://www.2daygeek.com/teleconsole-share-terminal-session-instantly-to-anyone-in-seconds/"},{default:s(()=>[...e[1]||(e[1]=[t("Teleconsole - 一個與其他人分享終端會話的工具",-1)])]),_:1})])]),e[36]||(e[36]=l("h3",{id:"如何安裝-tmux-命令",tabindex:"-1"},[t("如何安裝 tmux 命令 "),l("a",{class:"header-anchor",href:"#如何安裝-tmux-命令","aria-label":"Permalink to “如何安裝 tmux 命令”"},"​")],-1)),e[37]||(e[37]=l("p",null,"大多數 Linux 系統默認預安裝 tmux 命令。如果沒有，按照以下步驟安裝。",-1)),l("p",null,[e[4]||(e[4]=t("對於 Debian/Ubuntu，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-get-apt-cache-command-examples-manage-packages-debian-ubuntu-systems/"},{default:s(()=>[...e[2]||(e[2]=[t("APT-GET 命令",-1)])]),_:1}),e[5]||(e[5]=t("或 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-command-examples-manage-packages-debian-ubuntu-systems/"},{default:s(()=>[...e[3]||(e[3]=[t("APT 命令",-1)])]),_:1}),e[6]||(e[6]=t("來安裝：",-1))]),e[38]||(e[38]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install tmux</span></span></code></pre></div>',1)),l("p",null,[e[8]||(e[8]=t("對於 RHEL/CentOS，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/yum-command-examples-manage-packages-rhel-centos-systems/"},{default:s(()=>[...e[7]||(e[7]=[t("YUM 命令",-1)])]),_:1}),e[9]||(e[9]=t("來安裝：",-1))]),e[39]||(e[39]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tmux</span></span></code></pre></div>',1)),l("p",null,[e[11]||(e[11]=t("對於 Fedora，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/dnf-command-examples-manage-packages-fedora-system/"},{default:s(()=>[...e[10]||(e[10]=[t("DNF 命令",-1)])]),_:1}),e[12]||(e[12]=t("來安裝：",-1))]),e[40]||(e[40]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install tmux</span></span></code></pre></div>',1)),l("p",null,[e[14]||(e[14]=t("對於 Arch Linux，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/pacman-command-examples-manage-packages-arch-linux-system/"},{default:s(()=>[...e[13]||(e[13]=[t("Pacman 命令",-1)])]),_:1}),e[15]||(e[15]=t("來安裝：",-1))]),e[41]||(e[41]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S tmux</span></span></code></pre></div>',1)),l("p",null,[e[17]||(e[17]=t("對於 openSUSE，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/zypper-command-examples-manage-packages-opensuse-system/"},{default:s(()=>[...e[16]||(e[16]=[t("Zypper 命令",-1)])]),_:1}),e[18]||(e[18]=t("來安裝：",-1))]),e[42]||(e[42]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper in tmux</span></span></code></pre></div><h3 id="如何使用-tmux" tabindex="-1">如何使用 tmux <a class="header-anchor" href="#如何使用-tmux" aria-label="Permalink to “如何使用 tmux”">​</a></h3><p>在終端上運行以下命令來啓動 tmux 會話。啓動 tmux 後，它會在一個新窗口中創建新會話，並將使用你的用户賬户自動登錄到你的默認 shell。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-1.png" alt=""></p><p>你會得到類似於我們上面的截圖。tmux 附帶狀態欄，顯示有關當前會話詳細信息、日期、時間等。</p><p>狀態欄信息如下：</p><ul><li><code>[0]</code>：它表示由 tmux 服務器創建的會話號。默認情況下，它從 0 開始。</li><li><code>0:bash</code>：表示會話號、命令列提示符（這裏的 <code>bash</code> 表示 shell 名稱）。</li><li><code>*</code>：這表示該窗口現在處於活動狀態。</li><li>主機名：顯示服務器的完全主機名。</li><li>日期與時間：顯示當前日期和時間。</li></ul><p>（LCTT 譯註：tmux 的狀態可以根據需要定製，也會因環境、版本的不同而不同。）</p><h3 id="如何拆分窗口" tabindex="-1">如何拆分窗口 <a class="header-anchor" href="#如何拆分窗口" aria-label="Permalink to “如何拆分窗口”">​</a></h3><p>tmux 允許用户垂直或水平分割窗口，稱為窗格。每個窗格都包含自己獨立運行的終端實例。我們來看看如何做到這一點。</p><p>按下 <code>Ctrl+b, %</code> 來垂直分割窗格。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-2.png" alt=""></p><p>按下 <code>Ctrl+b, &quot;</code> 來水平分割窗格。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-3.png" alt=""></p><h3 id="如何在窗格之間移動" tabindex="-1">如何在窗格之間移動 <a class="header-anchor" href="#如何在窗格之間移動" aria-label="Permalink to “如何在窗格之間移動”">​</a></h3><p>假設，我們創建了一些窗格，希望在它們之間移動，這該怎麼做？如果你不知道怎麼做，那麼使用 tmux 就沒有意義了。使用以下控制鍵執行操作。在窗格之間移動有許多方法。</p><ul><li>按 <code>Ctrl+b, ←</code> - 選擇左邊的窗格</li><li>按 <code>Ctrl+b, →</code> - 選擇右邊的窗格</li><li>按 <code>Ctrl+b, ↑</code> - 選擇上邊的窗格</li><li>按 <code>Ctrl+b, ↓</code> - 選擇下邊的窗格</li><li>按 <code>Ctrl+b, {</code> - 來向左交換窗格</li><li>按 <code>Ctrl+b, }</code> - 來向右交換窗格</li><li>按 <code>Ctrl+b, o</code> - 切換到下一個窗格（從左到右，從上到下）</li><li>按 <code>Ctrl+b, ;</code> - 移動到先前活動的窗格</li></ul><p>出於測試目的，我們將在窗格之間移動。現在我們在 <code>pane2</code> 中，它展示了 <code>lsb_release -a</code> 命令的輸出。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-4.png" alt=""></p><p>我們將移動到 <code>pane0</code>，它顯示 <code>uname -a</code> 命令的輸出。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-5.png" alt=""></p><h3 id="如何打開-創建新窗口" tabindex="-1">如何打開/創建新窗口 <a class="header-anchor" href="#如何打開-創建新窗口" aria-label="Permalink to “如何打開/創建新窗口”">​</a></h3><p>你可以在一個終端內打開任意數量的窗口。</p><ul><li>按 <code>Ctrl+b, c</code> 來創建一個新窗口。</li><li>按 <code>Ctrl+b, n</code> 移動到下一個窗口。</li><li>按 <code>Ctrl+b, p</code> 移動到上一個窗口。</li><li>按 <code>Ctrl+b, 0</code> ~ <code>Ctrl+b, 9</code> 立即移動到特定窗口。</li><li>按 <code>Ctrl+b, l</code> 移動到先前選擇的窗口。</li></ul><p>我有兩個窗口，第一個窗口有三個窗格，其中包含操作系統版本信息，<code>top</code> 命令輸出和內核信息。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-8.png" alt=""></p><p>第二個窗口有兩個窗格，其中包含 Linux 發行版 logo 信息。使用以下命令執行操作：</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-6.png" alt=""></p><p>按 <code>Ctrl+b, w</code> 以交互方式選擇當前窗口。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-7.png" alt=""></p><h3 id="如何縮放窗格" tabindex="-1">如何縮放窗格 <a class="header-anchor" href="#如何縮放窗格" aria-label="Permalink to “如何縮放窗格”">​</a></h3><p>你正在一些非常小的窗格中工作，並且你希望將其縮小以進行進一步的工作。要做到這一點，使用以下鍵綁定。</p><p>目前我們有三個窗格，我在 <code>pane1</code> 工作，它使用 <code>top</code> 命令顯示系統活動信息，我將縮放它。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-8.png" alt=""></p><p>縮放窗格時，它將隱藏所有其它窗格，並只顯示窗口中的縮放窗格。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-9.png" alt=""></p><p>按 <code>Ctrl+b, z</code> 縮放窗格，並再次按下它使縮放窗格恢復原狀。</p><h3 id="顯示窗格信息" tabindex="-1">顯示窗格信息 <a class="header-anchor" href="#顯示窗格信息" aria-label="Permalink to “顯示窗格信息”">​</a></h3><p>要了解窗格編號及其大小，運行以下命令。</p><p>按 <code>Ctrl+b, q</code> 可簡單顯示窗格索引。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-10.png" alt=""></p><h3 id="顯示窗口信息" tabindex="-1">顯示窗口信息 <a class="header-anchor" href="#顯示窗口信息" aria-label="Permalink to “顯示窗口信息”">​</a></h3><p>要知道窗口編號、佈局大小，與窗口關聯的窗格數量及其大小等，運行以下命令。</p><p>只需運行 <code>tmux list-windows</code> 即可查看窗口信息。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-14.png" alt=""></p><h3 id="如何調整窗格大小" tabindex="-1">如何調整窗格大小 <a class="header-anchor" href="#如何調整窗格大小" aria-label="Permalink to “如何調整窗格大小”">​</a></h3><p>你可能需要調整窗格大小來滿足你的要求。你必須按下 <code>Ctrl+b, :</code>，然後在頁面底部的黃色顏色條上輸入以下詳細信息。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-11.png" alt=""></p><p>在上一部分中，我們打印了窗格索引，它同時也顯示了窗格大小。為了測試，我們要向增加 <code>10</code> 個單元。參考以下輸出，該窗格將 pane1 和 pane2 的大小從 <code>55x21</code> 增加到 <code>55x31</code>。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/01/tmux-a-powerful-terminal-multiplexer-emulator-for-linux-13.png" alt=""></p><p><strong>語法：</strong> <code>Ctrl+b, :</code> 然後輸入 <code>resize-pane [options] [cells size]</code></p><ul><li><code>Ctrl+b, :</code> 然後輸入 <code>resize-pane -D 10</code> 將當前窗格大小向下調整 10 個單元。</li><li><code>Ctrl+b, :</code> 然後輸入 <code>resize-pane -U 10</code> 將當前窗格大小向上調整 10 個單元。</li><li><code>Ctrl+b, :</code> 然後輸入 <code>resize-pane -L 10</code> 將當前窗格大小向左調整 10 個單元。</li><li><code>Ctrl+b, :</code> 然後輸入 <code>resize-pane -R 10</code> 將當前窗格大小向右調整 10 個單元。</li></ul><h3 id="分離並重新連接-tmux-會話" tabindex="-1">分離並重新連接 tmux 會話 <a class="header-anchor" href="#分離並重新連接-tmux-會話" aria-label="Permalink to “分離並重新連接 tmux 會話”">​</a></h3><p>tmux 最強大的功能之一是能夠在需要時分離和重新連接會話。</p><p>運行一個長時間運行的進程，然後按下 <code>Ctrl+b</code>，接着按 <code>d</code>，通過離開正在運行的進程安全地分離你的 tmux 會話。</p>',56)),l("p",null,[e[20]||(e[20]=l("strong",null,"建議閲讀：",-1)),e[21]||(e[21]=t()),i(a,{href:"https://www.2daygeek.com/how-to-keep-a-process-command-running-after-disconnecting-ssh-session/"},{default:s(()=>[...e[19]||(e[19]=[t("如何在斷開 SSH 會話後保持進程/命令繼續運行",-1)])]),_:1})]),e[43]||(e[43]=o(`<p>現在，運行一個長時間運行的進程。出於演示目的，我們將把此服務器備份移動到另一個遠程服務器以進行災難恢復（DR）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -avzhe ssh /backup root@192.168.0.161:/backups/week-1/</span></span></code></pre></div><p>在分離 tmux 會話之後，你將獲得類似下面的輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[detached (from session 0)]</span></span></code></pre></div><p>運行以下命令以列出可用的 tmux 會話。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux ls</span></span>
<span class="line"><span>0: 3 windows (created Tue Jan 30 06:17:47 2018) [109x45]</span></span></code></pre></div><p>現在，使用適當的會話 ID 重新連接 tmux 會話，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux attach -t 0</span></span></code></pre></div><h3 id="如何關閉窗格和窗口" tabindex="-1">如何關閉窗格和窗口 <a class="header-anchor" href="#如何關閉窗格和窗口" aria-label="Permalink to “如何關閉窗格和窗口”">​</a></h3><p>只需在相應的窗格中輸入 <code>exit</code> 或按下 <code>Ctrl-d</code> 即可關閉它，和終端關閉類似。要關閉窗口，按下 <code>Ctrl+b, &amp;</code>。</p><p>好了，就到這裏了，希望你喜歡上它。</p><hr>`,12)),l("p",null,[e[23]||(e[23]=t("via: ",-1)),i(a,{href:"https://www.2daygeek.com/tmux-a-powerful-terminal-multiplexer-emulator-for-linux/"},{default:s(()=>[...e[22]||(e[22]=[t("https://www.2daygeek.com/tmux-a-powerful-terminal-multiplexer-emulator-for-linux/",-1)])]),_:1})]),l("p",null,[e[27]||(e[27]=t("作者：",-1)),i(a,{href:"https://www.2daygeek.com/author/magesh/"},{default:s(()=>[...e[24]||(e[24]=[t("Magesh Maruthamuthu",-1)])]),_:1}),e[28]||(e[28]=t(" 譯者：",-1)),i(a,{href:"https://github.com/MjSeven"},{default:s(()=>[...e[25]||(e[25]=[t("MjSeven",-1)])]),_:1}),e[29]||(e[29]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[26]||(e[26]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[32]||(e[32]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[30]||(e[30]=[t("LCTT",-1)])]),_:1}),e[33]||(e[33]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:s(()=>[...e[31]||(e[31]=[t("Linux中國",-1)])]),_:1}),e[34]||(e[34]=t(" 榮譽推出",-1))])])}const C=n(u,[["render",m]]);export{w as __pageData,C as default};
